            Object response = (this.privatePostAccountBalances(parameters)).join();
            //
            //    {
            //        "success": true,
            //        "errorCode": "",
            //        "message": "",
            //        "result": {
            //            "USDT": {
            //              "available": "71.81328046",
            //              "freeze": "10.46103091"
            //            },
            //            "BTC": {
            //              "available": "0.00135674",
            //              "freeze": "0.00020003"
            //            }
